<?php
/** Default public publication search/archive fragment; copy follows public template locale, controls use finite GET filters and cards contain published projections only. */
declare(strict_types=1);
use function DBLESSCMS\e;
$q=$postsModel['query'];$action=$base_url.'/'.$postsSearch;
?>
<link rel="stylesheet" href="<?= e(\DBLESSCMS\asset('plugins/posts/css/public.css',$base_url)) ?>">
<section class="posts-public section"><div class="container"><header><h1><?= e($page['meta']['title']) ?></h1><p><?= e($page['meta']['description']) ?></p></header>
<form method="get" action="<?= e($action) ?>" class="posts-public-filters"><label><?= e($publicCopy['text']) ?><input type="search" name="q" maxlength="128" value="<?= e($q['q']) ?>"></label><label><?= e($publicCopy['type']) ?><select name="type" aria-label="<?= e($publicCopy['type']) ?>"><option value=""><?= e($publicCopy['all']) ?></option><?php foreach($postsTypes as $key=>$type): ?><option value="<?= e($key) ?>" <?= $q['type']===$key?'selected':'' ?>><?= e($type['plural']?:$publicCopy[$key==='page'?'pages':'articles']) ?></option><?php endforeach; ?></select></label><label><?= e($publicCopy['group']) ?><select name="group" aria-label="<?= e($publicCopy['group']) ?>"><option value=""><?= e($publicCopy['all']) ?></option><?php foreach($postsTerms['groups'] as $key=>$term):if($term['deleted'])continue; ?><option value="<?= e($key) ?>" <?= $q['group']===$key?'selected':'' ?>><?= e($term['name']) ?></option><?php endforeach; ?></select></label><label><?= e($publicCopy['tags']) ?><select name="tags[]" multiple size="3" aria-label="<?= e($publicCopy['tags']) ?>"><?php foreach($postsTerms['tags'] as $key=>$term):if($term['deleted'])continue; ?><option value="<?= e($key) ?>" <?= in_array($key,explode(',',$q['tags']),true)?'selected':'' ?>><?= e($term['name']) ?></option><?php endforeach; ?></select></label><button type="submit"><?= e($publicCopy['submit']) ?></button><a href="<?= e($action) ?>"><?= e($publicCopy['clear']) ?></a></form>
<p role="status"><?= e($publicCopy['results']) ?>: <?= $postsModel['total'] ?></p>
<?php if($postsModel['items']===[]): ?><p><?= e($publicCopy['empty']) ?></p><?php else: ?><div class="posts-public-grid"><?php foreach($postsModel['items'] as $item): ?><article><?php if($item['image']!==''): ?><img src="<?= e(preg_match('~^https?://~i',$item['image'])?$item['image']:$base_url.'/'.ltrim($item['image'],'/')) ?>" alt="<?= e($item['imageAlt']) ?>" loading="lazy"><?php endif; ?><h2><a href="<?= e($item['url']) ?>"><?= e($item['title']) ?></a></h2><p><?= e($item['summary']) ?></p><?php if($item['publishedAt']!==''): ?><time datetime="<?= e($item['publishedAt']) ?>"><?= e(substr($item['publishedAt'],0,10)) ?></time><?php endif; ?><p><?= e($item['author']) ?></p></article><?php endforeach; ?></div><?php endif; ?>
<?php if($postsModel['pages']>1): ?><nav class="posts-public-pagination" aria-label="<?= e($publicCopy['results']) ?>"><?php if($postsModel['hasPrevious']): ?><a rel="prev" href="<?= e($action.'?'.http_build_query(array_replace($q,['page'=>$postsModel['page']-1]))) ?>"><?= e($publicCopy['previous']) ?></a><?php endif; ?><span aria-current="page"><?= $postsModel['page'] ?> / <?= $postsModel['pages'] ?></span><?php if($postsModel['hasNext']): ?><a rel="next" href="<?= e($action.'?'.http_build_query(array_replace($q,['page'=>$postsModel['page']+1]))) ?>"><?= e($publicCopy['next']) ?></a><?php endif; ?></nav><?php endif; ?>
</div></section>
